import { localImageManifest } from "@/data/local-image-manifest";

export type LocalPlaceImages = { hero?: string; gallery?: string[] };

/**
 * Locally hosted imagery, keyed by place slug. The manifest is generated by
 * `npm run images:localize`, which downloads each remote hero/gallery image
 * into `public/images/places/` so pages no longer hot-link third-party sites.
 * Returns undefined when a place has no local copy yet; callers then fall back
 * to the remote URL in the source data (or the editorial placeholder).
 */
export function localPlaceImages(slug: string): LocalPlaceImages | undefined {
  return localImageManifest[slug];
}
